import{d as s,C as t,o as h,c as u,E as a,a3 as n}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"复卦","description":"第二十四卦·地雷复——雷在地中，一阳来复。","frontmatter":{"title":"复卦","description":"第二十四卦·地雷复——雷在地中，一阳来复。","category":"hexagram","aliases":["复","地雷复"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-24.md","filePath":"yijing/hexagrams/hexagram-24.md","lastUpdated":1787730063000}'),g={name:"yijing/hexagrams/hexagram-24.md"},y=s({...g,setup(p){const l=[{id:"buyuanfu",term:"不远复",pinyin:"bù yuǎn fù",meaning:"偏离不远就回来。最好的复，是在偏离刚发生的时候就回来。"},{id:"wuzhihui",term:"无祗悔",pinyin:"wú zhī huǐ",meaning:"不至于悔恨。祗，仅仅、至于。刚偏就回，自然无悔。"},{id:"xiufu",term:"休复",pinyin:"xiū fù",meaning:"美好的回归。靠近善、借力回，不孤军奋战。"},{id:"pinfu",term:"频复",pinyin:"pín fù",meaning:"屡次反复、挣扎着回来。蹙眉、承认沉没成本也愿意回。"},{id:"zhongxingdufu",term:"中行独复",pinyin:"zhōng xíng dú fù",meaning:"行于中道、独自回归。看见方向，特立独行地走过去。"},{id:"dunfu",term:"敦复",pinyin:"dūn fù",meaning:"敦厚而回归。多次积累后的厚度，收成了本能。"},{id:"mifu",term:"迷复",pinyin:"mí fù",meaning:"迷失于回归。为了复而复，方向从未对过。"},{id:"zaisheng",term:"灾眚",pinyin:"zāi shěng",meaning:"灾祸。眚，过失、灾异。"},{id:"yixiushen",term:"以修身",pinyin:"yǐ xiū shēn",meaning:"用来修养身心。不远之复，以修身也——最初就觉察，是最好的修身。"},{id:"yixiaren",term:"以下仁",pinyin:"yǐ xià rén",meaning:"因为亲附仁者。休复之吉，以下仁也——选择和谁在一起，本身就是一种复。"},{id:"yiwujiu",term:"义无咎",pinyin:"yì wú jiù",meaning:"义理上无咎。频复之厉，义无咎也——不是没有损失，是没有骗自己。"},{id:"yicongdao",term:"以从道",pinyin:"yǐ cóng dào",meaning:"因为跟从正道。中行独复，以从道也。"},{id:"zhongyizikao",term:"中以自考",pinyin:"zhōng yǐ zì kǎo",meaning:"居中而自我省察。敦复无悔，中以自考也。"},{id:"fanjundao",term:"反君道",pinyin:"fǎn jūn dào",meaning:"违反君道。迷复之凶，反君道也——忘记了为什么要回。"}],e=[{position:"初九",type:"yang",text:"不远复，无祗悔，元吉。",xiang:"不远之复，以修身也。",textModern:"刚刚偏离，还没走远，回头是自然的，代价几乎为零。元吉不是奖励，是描述——在最早的时刻认出偏离、转身，本来就是这样的结果。",xiangModern:"偏离不远就回归，用来修养身心——在最初就觉察，是最好的修身。"},{position:"六二",type:"yin",text:"休复，吉。",xiang:"休复之吉，以下仁也。",textModern:"靠近善、借力回——六二本身是阴爻，但紧靠初九这个阳爻，被正确的环境带回来。复不一定要孤军奋战。",xiangModern:"休复的吉，在于亲附仁者——选择和谁在一起，本身就是一种复。"},{position:"六三",type:"yin",text:"频复，厉，无咎。",xiang:"频复之厉，义无咎也。",textModern:"走得比六二远，回头意味着承认之前的投入不算数——沉没成本的重量。但清清楚楚知道代价，还是转身了；全程清醒、全程诚实，所以无咎。",xiangModern:"频复的厉，在义理上无咎——不是没有损失，是因为没有骗自己。"},{position:"六四",type:"yin",text:"中行独复。",xiang:"中行独复，以从道也。",textModern:"被五个阴爻包围，待着很安全，但它看见了下面的初九，选择独自往那里走。这个独不是孤独，是特立独行的独——看见方向，平静地走过去。",xiangModern:"行于中道而独自回归，因为跟从正道——不随波逐流不是目的，看见初九并走过去才是。"},{position:"六五",type:"yin",text:"敦复，无悔。",xiang:"敦复无悔，中以自考也。",textModern:"多次积累后的厚度——经历了足够多次的频复、独复、挣扎着复，内心生出一种东西：不需要再证明、再解释，厚在那里，就是那里。收，变成了本能。",xiangModern:"敦复而无悔，在于居中而自我省察——该放下就放下，放完了心里干净。"},{position:"上六",type:"yin",text:"迷复，凶，有灾眚。用行师，终有大败，以其国君凶，至于十年不克征。",xiang:"迷复之凶，反君道也。",textModern:"为了复而复，方向从未对过——形式还在，灵魂没了。不是不努力，是在迷宫里跑圈，跑得越快，离出口越远；灾眚不是天降惩罚，是长期在错误方向上消耗自己。",xiangModern:"迷复的凶，在于违反君道——忘记了为什么要回，只记得要回这个动作本身。"}];return(m,i)=>{const o=t("DaoHexagramViewer"),r=t("DaoHexagramYaoCards"),d=t("DaoKeywordCards");return h(),u("div",null,[a(o,{name:"复",fullName:"地雷复",upper:"☷",lower:"☳",guaCi:"复，亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。",pinyin:["fù"],element:"土",direction:"西南",insight:"一阳来复，阳气萌生；复不是动作，是清醒，清醒的质量决定复的质量。",guaSlug:"24dileifu",lines:e}),i[0]||(i[0]=n('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>雷在地中，复。先王以至日闭关，商旅不行，后不省方。</p><p>下震为雷、上坤为地，雷藏于地中，是阳气初复、尚需休养之象。先王由此悟到：在冬至（一阳来复之日）关闭关卡、商旅不行、君王也不省察四方——<strong>给那一点刚萌生的阳气，留出安静生长的时间</strong>。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>复亨，刚反。动而以顺行，是以出入无疾，朋来无咎。反复其道，七日来复，天行也。利有攸往，刚长也。复，其见天地之心乎。</p><p>逐句释义：</p><ul><li><strong>复亨，刚反</strong> —— 复卦亨通，因为阳刚返回来（初九一阳来复）。</li><li><strong>动而以顺行，是以出入无疾，朋来无咎</strong> —— 下震为动、上坤为顺，动而顺行，所以出入无疾、朋来无咎。</li><li><strong>反复其道，七日来复，天行也</strong> —— 反复循环，七日一复，这是天道运行。</li><li><strong>利有攸往，刚长也</strong> —— 利于有所前往，因为阳刚正在生长。</li><li><strong>复，其见天地之心乎</strong> —— 复卦，难道不是显现了天地之心吗！</li></ul><blockquote><p><strong>七日来复</strong>：复是十二消息卦之一，阳气从冬至开始回升，七日一个循环。阳气自然回归，天道如此，人道亦然。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',9)),a(r,{element:"土",guaSlug:"24dileifu",glossary:l,items:e}),i[1]||(i[1]=n('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-不远复-无祗悔-元吉" tabindex="-1">初九 · 不远复，无祗悔，元吉 <a class="header-anchor" href="#初九-·-不远复-无祗悔-元吉" aria-label="Permalink to &quot;初九 · 不远复，无祗悔，元吉&quot;">​</a></h3><ul><li>初九是整个复卦最好的状态</li><li>刚刚偏离，还没走远，回头是自然的，代价几乎为零</li><li><strong>元吉不是奖励，是描述</strong>——在最早的时刻认出了偏离、转身，本来就是这样的结果</li></ul><blockquote><p>最好的复，是在偏离刚发生的时候就回来。不需要挣扎，不需要代价，只需要足够敏锐。</p></blockquote><h3 id="六二-·-休复-吉" tabindex="-1">六二 · 休复，吉 <a class="header-anchor" href="#六二-·-休复-吉" aria-label="Permalink to &quot;六二 · 休复，吉&quot;">​</a></h3><ul><li>六二本身是阴爻，但它紧靠着初九这个阳爻</li><li>它的复，不完全靠自己，是因为靠近了正确的人、正确的环境，被带回来的</li><li><strong>休复</strong>：美好的回归</li></ul><blockquote><p>复不一定要孤军奋战。选择和谁在一起，本身就是一种复。</p></blockquote><h3 id="六三-·-频复-厉-无咎" tabindex="-1">六三 · 频复，厉，无咎 <a class="header-anchor" href="#六三-·-频复-厉-无咎" aria-label="Permalink to &quot;六三 · 频复，厉，无咎&quot;">​</a></h3><ul><li>六三走得比六二远，回头意味着承认之前的投入不算数——这就是沉没成本的重量</li><li>但六三不是不知道代价，它清清楚楚知道，然后还是转身了</li><li><strong>无咎不是因为没有损失，是因为它没有骗自己</strong>——全程清醒，全程诚实</li></ul><p>某个功能做了很久、某个方向投入了很多，发现它偏了——那个时刻，蹙眉是真实的，但认知到了还是愿意复，厉，无咎。</p><blockquote><p>糊涂地回来不算数，挣扎着、皱着眉、清醒地回来，才是真正的复。</p></blockquote><h3 id="六四-·-中行独复" tabindex="-1">六四 · 中行独复 <a class="header-anchor" href="#六四-·-中行独复" aria-label="Permalink to &quot;六四 · 中行独复&quot;">​</a></h3><ul><li>六四被五个阴爻包围，待着很安全，没有人逼你走、没有人说你错</li><li>但它看见了下面的初九，选择独自往那里走</li><li><strong>这个「独」不是孤独</strong>，是特立独行的独——看见了正确，平静地走过去</li></ul><blockquote><p>不随波逐流不是目的，看见那个初九并且走过去，才是。</p></blockquote><h3 id="六五-·-敦复-无悔" tabindex="-1">六五 · 敦复，无悔 <a class="header-anchor" href="#六五-·-敦复-无悔" aria-label="Permalink to &quot;六五 · 敦复，无悔&quot;">​</a></h3><ul><li><strong>敦</strong>：厚重、笃实、朴素的重</li><li>无悔是所有次数叠加之后的状态——不是量变，是质变</li><li>六五是多次六三积累下来的厚度：经历了足够多次的频复、独复、挣扎着复，内心生出「厚」，不需要再证明、再解释</li></ul><p><strong>德州扑克的比喻</strong>：拿了对 A，但局面告诉你该 fold，fold 了，这是得不是失——能放下好牌的人，才是真正懂牌的人。</p><blockquote><p>不是大了才知道收，是经历了足够多次之后，收变成了本能。敦，就是这个本能积累出来的厚度。</p></blockquote><h3 id="上六-·-迷复-凶-有灾眚" tabindex="-1">上六 · 迷复，凶，有灾眚 <a class="header-anchor" href="#上六-·-迷复-凶-有灾眚" aria-label="Permalink to &quot;上六 · 迷复，凶，有灾眚&quot;">​</a></h3><ul><li>上六的复，是忘记了为什么要回，只记得要回这个动作本身——形式还在，灵魂没了</li><li><strong>好奇心死掉的那一刻，就是迷复开始的那一刻</strong>：为了刷题而刷题，不再问这道题在告诉我什么</li><li>迷复的人不是不努力，他的努力是在迷宫里跑圈，跑得越快，离出口越远</li><li><strong>灾眚不是天降的惩罚</strong>，是一个人长期在错误方向上消耗自己，最终把自己耗尽了</li></ul><blockquote><p>十年不克征，不是因为停下来了，是因为一直在跑，但方向从来没有对过。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',22)),a(d,{title:"字词释义",items:[{term:"复",pinyin:["fù"],meaning:"回来。不是终点，是重新找到方向的起点。"},{term:"不远复",pinyin:["bù","yuǎn","fù"],meaning:"偏离不远就回来。"},{term:"休复",pinyin:["xiū","fù"],meaning:"美好的回归，靠近善、借力回。"},{term:"频复",pinyin:["pín","fù"],meaning:"屡次反复、挣扎着回来。"},{term:"中行独复",pinyin:["zhōng","xíng","dú","fù"],meaning:"行于中道、独自回归。"},{term:"敦复",pinyin:["dūn","fù"],meaning:"敦厚而回归，收成了本能。"},{term:"迷复",pinyin:["mí","fù"],meaning:"迷失于回归，为了复而复。"},{term:"祗",pinyin:["zhī"],meaning:"仅仅、至于。「无祗悔」即不至于悔恨。"},{term:"灾眚",pinyin:["zāi","shěng"],meaning:"灾祸。眚，过失、灾异。"},{term:"七日来复",pinyin:["qī","rì","lái","fù"],meaning:"阳气七日一循环，天道如此，人道亦然。"}]}),i[2]||(i[2]=n('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>复卦讲的是<strong>回归</strong>。一阳在下、五阴在上，阳气刚刚萌生，微弱但真实——复的种子，就在最底下那一点。</p><p>卦辞「亨，出入无疾，朋来无咎，反复其道，七日来复，利有攸往」点明：阳气自然回归，天道如此，人道亦然。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>复不是动作，是清醒。清醒的质量，决定复的质量：</p><ul><li>刚偏就回（初九不远复）</li><li>借力回（六二休复）</li><li>清醒挣扎回（六三频复）</li><li>独回（六四中行独复）</li><li>厚了、稳了（六五敦复）</li><li>迷了（上六迷复）</li></ul><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>在最早的时刻认出偏离（不远复）</li><li>靠近正确的人和事（休复）</li><li>清醒地承担沉没成本（频复）</li><li>看见方向就走（中行独复）</li><li>把「收」变成本能（敦复）</li><li>警惕为了复而复（迷复）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六爻总览：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞</th><th>核心</th><th>结果</th></tr></thead><tbody><tr><td>初九</td><td>不远复，无祗悔</td><td>刚偏就回，自然无悔</td><td>元吉</td></tr><tr><td>六二</td><td>休复</td><td>靠近善，借力回</td><td>吉</td></tr><tr><td>六三</td><td>频复，厉</td><td>清醒挣扎，沉没成本也愿意放</td><td>无咎</td></tr><tr><td>六四</td><td>中行独复</td><td>安全感中，特立独行往正确走</td><td>—</td></tr><tr><td>六五</td><td>敦复</td><td>多次积累后的厚度，收成本能</td><td>无悔</td></tr><tr><td>上六</td><td>迷复，凶</td><td>为了复而复，方向从未对过</td><td>凶</td></tr></tbody></table><p>复卦的一条线（偏离程度递增）：</p><ul><li>初九：刚刚偏，马上回</li><li>六二：偏了一点，有人拉</li><li>六三：偏了一段，代价大，还是回</li><li>六四：被包围，还是认得出方向</li><li>六五：来回多次，厚了，稳了</li><li>上六：迷了，不知道为什么要回了</li></ul><p><strong>最底层的一句话</strong>：</p><ul><li>你回来了，但不知道为什么回——迷复，凶</li><li>你回来了，清清楚楚知道代价——无咎</li><li>你回来了，回了很多次，心里干净——无悔</li></ul><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>复卦与实践：</p><p>每一次回头，你知道你在回到哪里吗？你还记得那个初九吗？</p><ul><li>记得，就复。</li><li>忘了，先找回那个初九，再复。</li><li>否则，再多的迭代，都是迷宫里跑圈。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：剥（第二十三卦）、无妄（第二十五卦）</li><li>剥与复：剥极必复——阴剥到尽头，一阳来复</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',22))])}}});export{x as __pageData,y as default};
